-- ============================================================
-- Migration: Replace ALL daerah data with updated CSV
-- Source: docs/daerah_updated.csv
-- Generated: 2026-02-19 13:15:05
-- Total rows: 548 (Provinsi: 34, Kab/Kota: 514)
-- ============================================================
-- WARNING: This will TRUNCATE daerah table CASCADE.
-- All FK references (users.daerah_id, events.daerah_id, etc.) will be affected.
-- Only run this on a fresh/dev database or when data loss is acceptable.
-- ============================================================

BEGIN;

-- Step 1: Clear all existing daerah data (CASCADE to FKs)
TRUNCATE TABLE daerah CASCADE;

-- Step 2: Insert Provinsi (34 rows)

-- Step 3: Insert Kabupaten & Kota (514 rows)
-- parent_id is resolved via subquery on province kode

-- Step 4: Verification
DO $$
DECLARE
  v_total INTEGER;
  v_prov INTEGER;
  v_kab INTEGER;
  v_kota INTEGER;
  v_orphan INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_total FROM daerah;
  SELECT COUNT(*) INTO v_prov FROM daerah WHERE level = 'provinsi';
  SELECT COUNT(*) INTO v_kab FROM daerah WHERE level = 'kabupaten';
  SELECT COUNT(*) INTO v_kota FROM daerah WHERE level = 'kota';
  SELECT COUNT(*) INTO v_orphan FROM daerah WHERE level != 'provinsi' AND parent_id IS NULL;

  RAISE NOTICE 'Daerah migration verification:';
  RAISE NOTICE '  Total: % rows', v_total;
  RAISE NOTICE '  Provinsi: %', v_prov;
  RAISE NOTICE '  Kabupaten: %', v_kab;
  RAISE NOTICE '  Kota: %', v_kota;
  RAISE NOTICE '  Orphan kab/kota (should be 0): %', v_orphan;

  IF v_total != 548 THEN
    RAISE EXCEPTION 'Row count mismatch! Expected 548, got %', v_total;
  END IF;
  IF v_orphan != 0 THEN
    RAISE EXCEPTION 'Found % orphan kab/kota without parent!', v_orphan;
  END IF;
END
$$;

COMMIT;

